shader => {
    shader.uniforms.bileTime = clock; shader.uniforms.bileWarning = warning;
    shader.vertexShader = shader.vertexShader.replace('#include <common>',
      '#include <common>\nuniform float bileTime; varying vec3 bilePos; varying vec2 bileUV;')
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        bilePos = position; bileUV = uv;
        float edgeFade = sin(uv.x * 3.14159265) * sin(uv.y * 3.14159265);
        transformed.y += edgeFade * (sin(position.x * 2.3 + bileTime * 1.7) * 0.065
          + cos(position.z * 2.8 - bileTime * 1.2) * 0.045);`);
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>',
      '#include <common>\nuniform float bileTime, bileWarning; varying vec3 bilePos; varying vec2 bileUV;' + BUMP_GLSL)
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
        // two crossing ripple trains + a slow swell: the tilted normal smears the highlights like refraction
        vec2 bq = bilePos.xz;
        float ripple = sin(bq.x * 5.1 + bileTime * 2.1 + sin(bq.y * 1.3)) * sin(bq.y * 4.3 - bileTime * 1.7)
          + 0.5 * sin(dot(bq, vec2(2.7, -3.9)) + bileTime * 2.9) + 0.35 * sin(length(bq) * 1.6 - bileTime * 0.9);
        normal = flBump(-vViewPosition, normal, ripple * 0.05, 1.0);`)
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        float flow = sin(bilePos.x * 3.4 + sin(bilePos.z * 2.2 + bileTime * 0.7) - bileTime);
        float foam = smoothstep(0.7, 0.98, flow) * 0.07;
        float edge = min(bileUV.y, 1.0 - bileUV.y);
        float foamN = 0.5 + 0.5 * sin(bilePos.x * 9.0 + bileTime * 1.3) * sin(bilePos.z * 8.0 - bileTime * 1.1);
        float shore = 1.0 - smoothstep(0.0, 0.06 + 0.07 * foamN, edge);
        // depth: the middle of the pool reads deep and murky, the shallows lighter and yellower
        float deep = smoothstep(0.05, 0.45, edge);
        diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(0.32, 0.42, 0.18), deep * 0.85);
        diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.74, 0.8, 0.36), foam + shore * (0.35 + 0.3 * foamN));
        // caustic web glowing up from beneath the surface
        vec2 cq = bilePos.xz * 1.3 + vec2(sin(bilePos.z * 0.7 + bileTime * 0.3), cos(bilePos.x * 0.6 - bileTime * 0.25)) * 1.2;
        float caus = abs(sin(cq.x + sin(cq.y * 1.3 + bileTime * 0.8) * 1.4) * sin(cq.y + sin(cq.x * 1.1 - bileTime * 0.6) * 1.4));
        caus = pow(1.0 - caus, 9.0) * (0.5 + 0.5 * sin(bilePos.x * 0.9 + bilePos.z * 1.1 + bileTime * 0.4));
        totalEmissiveRadiance += vec3(0.04, 0.06, 0.003) * (foam * 2.0 + bileWarning * 0.25)
          + vec3(0.045, 0.065, 0.006) * caus * (0.4 + 0.6 * deep) * (1.0 + bileWarning)
          + vec3(0.05, 0.06, 0.02) * shore * foamN;`);
  }

